func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	scores := make(map[string]float64, len(snapshots))

	// Find min load for relative penalty
	minLoad := snapshots[0].EffectiveLoad()
	maxLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if el > maxLoad {
			maxLoad = el
		}
	}

	// Adaptive weights: sessions favor prefix-affinity, high load favors load-balance
	loadPressure := float64(maxLoad) / (float64(maxLoad) + 3.5)
	dynWeights := make([]float64, len(ws.weights))
	copy(dynWeights, ws.weights)
	if len(dynWeights) >= 2 {
		if req.SessionID != "" {
			// Sessions: strong prefix affinity but allow some load balancing under pressure
			dynWeights[0] = 2.8 - 0.6*loadPressure
			dynWeights[1] = 0.4 + 0.8*loadPressure
		} else {
			// Non-sessions: shift more aggressively toward load-balance under pressure
			dynWeights[0] = 1.0 - 0.8*loadPressure
			dynWeights[1] = 1.0 + 1.8*loadPressure
		}
		wSum := dynWeights[0] + dynWeights[1]
		if wSum > 0.001 {
			for k := range dynWeights {
				dynWeights[k] /= wSum
			}
		}
	}

	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * dynWeights[i]
		}
	}

	for _, snap := range snapshots {
		// Stronger cache bonus - helps cache_warmup workload significantly
		scores[snap.ID] += 0.20 * snap.CacheHitRate

		// More aggressive KV memory pressure penalties
		if snap.KVUtilization > 0.82 {
			scores[snap.ID] *= 0.25
		} else if snap.KVUtilization > 0.68 {
			scores[snap.ID] *= 0.65
		}

		// Exponential load penalty - avoids hotspots more aggressively
		loadDiff := float64(snap.EffectiveLoad() - minLoad)
		if loadDiff > 0 {
			scores[snap.ID] *= 1.0 / (1.0 + 0.6*loadDiff + 0.08*loadDiff*loadDiff)
		}

		// Stronger queue depth penalty - queue is primary latency driver
		if snap.QueueDepth > 5 {
			scores[snap.ID] *= 0.35
		} else if snap.QueueDepth > 3 {
			scores[snap.ID] *= 0.75
		}

		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
